    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handlePluginLink(intent);}
    private void handlePluginLink(Intent intent){Uri uri=intent==null?null:intent.getData();if(uri==null||!"mygo-music".equals(uri.getScheme())||!"install-plugin".equals(uri.getHost()))return;String repo=uri.getQueryParameter("repo");if(repo==null||!repo.matches("[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+")){showPluginError("插件链接缺少有效仓库地址");return;}setIntent(new Intent(intent).setData(null));new AlertDialog.Builder(this).setTitle("安装音乐源插件").setMessage("仓库："+repo+"\n安装后可查看账号、权限与可用性检查。网络和辅助程序权限由你单独授权。").setNegativeButton("取消",null).setPositiveButton("下载安装",(dialog,which)->pluginManager.installFromGitHub(repo,(ok,raw)->runOnUiThread(()->{if(ok){refreshSourceTabs();showPlugins();}else showPluginError(raw);}))).show();}
