    private void playSourceQueue(PluginManager.PluginInfo source,ArrayList<JSONObject> items,int index){
        if(index<0||index>=items.size())return;final long request=++playRequest;final String quality=AudioQuality.normalize(prefs.getString("play_quality",AudioQuality.DEFAULT));final JSONArray queue=new JSONArray();int selected=-1;
        int first=(index/500)*500;for(int i=first;i<items.size()&&queue.length()<500;i++){JSONObject item=items.get(i);String id=item.optString("id");if(id.isEmpty()||item.optBoolean("unavailable"))continue;
            Uri uri=new Uri.Builder().scheme("plugin").authority(source.id).appendQueryParameter("id",id).build();String title=SourceBrowser.trackName(item);int found=tracks.indexOf(uri);if(found<0){tracks.add(uri);names.add(title);}else names.set(found,title);pluginTrackRefs.put(uri.toString(),source.id+"\n"+id);String art=SourceBrowser.artwork(item);if(!art.isEmpty())covers.put(uri.toString(),art);
            trackMetadata.put(uri.toString(),item);if(i==index)selected=queue.length();try{queue.put(new JSONObject().put("uri",uri.toString()).put("title",title).put("track",item).put("stationId",item.optString("_stationId")));}catch(JSONException ignored){}
        }
        if(selected<0&&index==0&&queue.length()>0)selected=0;if(selected<0){showPluginError("这首歌曲暂不可播放");return;}saveLibrary();saveCovers();saveTrackMetadata();if(adapter!=null)adapter.notifyDataSetChanged();final int start=selected;String uri=queue.optJSONObject(start).optString("uri");Runnable begin=()->{if(isDestroyed()||request!=playRequest)return;try{PlaybackService.startQueue(this,queue,start,0,volume.getProgress(),shuffle,repeat,AudioQuality.normalize(prefs.getString("play_quality",AudioQuality.DEFAULT)));}catch(Exception error){showPluginError(error.getMessage());}};
        if(audioCache.find(uri,quality)!=null)begin.run();else pluginManager.authorizeSource(source.id,(ok,raw)->{if(request!=playRequest)return;if(ok)begin.run();else showPluginError(raw);});
    }

    private final ExecutorService artworkExecutor=Executors.newFixedThreadPool(3);
    private final android.util.LruCache<String,Bitmap> artworkCache=new android.util.LruCache<>(24);
    private void loadGridArtwork(ImageView view,String address,String sourceId){
        if(address==null||!address.startsWith("http"))return;address=PluginProtocol.image(address,Math.max(80,view==coverArt?600:view.getWidth()>0?view.getWidth():240));final String resolvedAddress=address;
        final HashMap<String,String> headers;try{headers=pluginManager.mediaHeaders(sourceId,address,"image",null);}catch(Exception ignored){return;}
        // Include account-dependent headers in the cache key, never in URLs or logs.
        String cacheKey=sourceId+"\n"+address+"\n"+new java.util.TreeMap<>(headers).toString();view.setTag(cacheKey);Bitmap cached=artworkCache.get(cacheKey);if(cached!=null){view.setImageBitmap(cached);if(view==coverArt)updateLyricsArtwork();return;}
        artworkExecutor.execute(()->{try(PluginMedia.Connection connection=PluginMedia.open(resolvedAddress,headers,false);InputStream input=connection.http.getInputStream()){
            ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1){if(bytes.size()+n>4*1024*1024)throw new IOException("封面超过大小限制");bytes.write(buffer,0,n);}byte[] data=bytes.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>400||options.outHeight/options.inSampleSize>400)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(data,0,data.length,options);if(bitmap!=null){artworkCache.put(cacheKey,bitmap);runOnUiThread(()->{if(!isDestroyed()&&cacheKey.equals(view.getTag())){view.setImageBitmap(bitmap);if(view==coverArt)updateLyricsArtwork();}});}
        }catch(Exception ignored){}});
    }
    private String artworkSource(Uri uri){return "plugin".equals(uri.getScheme())?uri.getAuthority():"";}
    private void refreshLandscapeGrid(){if(landscapeGrid==null||(sourceBrowser!=null&&sourceBrowser.active()))return;if(landscapeShortcuts!=null)landscapeShortcuts.setVisibility(View.VISIBLE);landscapeGrid.removeAllViews();if(names.isEmpty()){landscapeGrid.addView(text("暂无歌曲，先搜索在线音乐或添加本地文件",15,Color.rgb(190,185,195)),new LinearLayout.LayoutParams(-1,dp(64)));return;}int cardHeight=Math.max(88,Math.min(142,(int)(getResources().getDisplayMetrics().heightPixels/getResources().getDisplayMetrics().density)-244));LinearLayout row=null;int count=0;for(int i=0;i<names.size()&&i<60;i++){if(count%4==0){row=new LinearLayout(this);row.setPadding(0,dp(4),0,dp(4));landscapeGrid.addView(row,new LinearLayout.LayoutParams(-1,dp(cardHeight+8)));}LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(6),dp(6),dp(6),dp(6));card.setBackground(bg(Color.rgb(37,33,42),12));ImageView cover=new ImageView(this);cover.setImageResource(com.mygo.music.R.drawable.ic_launcher);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(cover,new LinearLayout.LayoutParams(-1,dp(cardHeight-44)));loadGridArtwork(cover,covers.get(tracks.get(i).toString()),artworkSource(tracks.get(i)));TextView title=text(names.get(i),12,Color.WHITE);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(title,new LinearLayout.LayoutParams(-1,dp(32)));final int index=i;card.setOnClickListener(v->playIndex(index));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,dp(cardHeight),1);params.setMargins(0,0,dp(4),0);row.addView(card,params);count++;}if(row!=null)while(count%4!=0){row.addView(new View(this),new LinearLayout.LayoutParams(0,dp(cardHeight),1));count++;}}
    private void landscapeSearch(String query){
        if(query.isEmpty()){PluginManager.PluginInfo selected=selectedSource();if(sourceBrowser!=null&&sourceBrowser.active()&&selected!=null)selectSource(selected);else refreshLandscapeGrid();return;}
        PluginManager.PluginInfo source=selectedSource();if(source==null){showPluginError("先安装并启用一个音乐源插件");showPlugins();return;}if(!source.supports("search")){showPluginError("此音乐源没有提供搜索接口，请切换音乐源");return;}
        ensureSourceBrowser();if(landscapeShortcuts!=null)landscapeShortcuts.setVisibility(View.GONE);landscapeSource=source.id;prefs.edit().putString("selected_source",source.id).apply();refreshSourceTabs();if(!source.id.equals(sourceBrowser.sourceId()))sourceBrowser.select(source);sourceBrowser.search(query,searchKind);
    }
