    private void pickAudio(){ Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT); i.setType("audio/*"); i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true); i.addCategory(Intent.CATEGORY_OPENABLE); i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION); startActivityForResult(i,PICK_AUDIO); }
    @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==SAVE_LOGIN_QR){Bitmap bitmap=pendingLoginQr;Runnable saved=pendingLoginQrSaved;pendingLoginQr=null;pendingLoginQrSaved=null;try{if(c==RESULT_OK&&d!=null&&bitmap!=null){try(OutputStream out=getContentResolver().openOutputStream(d.getData())){if(out==null||!bitmap.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException();}Toast.makeText(this,"二维码已保存，请在本机扫码应用中从相册选择",Toast.LENGTH_LONG).show();if(saved!=null)saved.run();}}catch(Exception error){showPluginError("二维码保存失败");}finally{if(bitmap!=null)bitmap.recycle();}return;}if(c==RESULT_OK&&d!=null&&r==PICK_PLUGIN){pluginManager.installZip(d.getData(),(ok,message)->runOnUiThread(()->{if(ok){refreshSourceTabs();showPlugins();}else showPluginError(message);}));return;}if(c==RESULT_OK&&d!=null&&r==EXPORT_DATA){writeBackup(d.getData());return;}if(c==RESULT_OK&&d!=null&&r==IMPORT_DATA){readBackup(d.getData());return;}if(c==RESULT_OK&&d!=null&&r==PICK_LRC){readLocalLyrics(d.getData());return;}if(r!=PICK_AUDIO||c!=RESULT_OK||d==null)return;try{if(d.getClipData()!=null){for(int i=0;i<d.getClipData().getItemCount();i++){Uri u=d.getClipData().getItemAt(i).getUri();persist(u);add(u);}}else if(d.getData()!=null){persist(d.getData());add(d.getData());}}catch(Exception ignored){}adapter.notifyDataSetChanged();refreshLandscapeGrid(); if(headingView!=null)headingView.setText("本地歌曲  ·  "+names.size());}
    private void persist(Uri u){try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}}
    private void loadLibrary(){StringJoiner us=new StringJoiner("\n");String raw=prefs.getString("uris","");String ns=prefs.getString("names","");if(raw.isEmpty())return;String[] a=raw.split("\\n",-1),b=ns.split("\\n",-1);for(int i=0;i<a.length;i++)try{tracks.add(Uri.parse(a[i]));if(a[i].startsWith("plugin:")){Uri pu=Uri.parse(a[i]);pluginTrackRefs.put(a[i],pu.getAuthority()+"\n"+pu.getQueryParameter("id"));}names.add(i<b.length?b[i]:a[i]);}catch(Exception ignored){}}
    private void saveLibrary(){StringJoiner u=new StringJoiner("\n"),n=new StringJoiner("\n");for(Uri x:tracks)u.add(x.toString());for(String x:names)n.add(x);prefs.edit().putString("uris",u.toString()).putString("names",n.toString()).apply();}
    private void removeTrack(int i){if(i<0||i>=tracks.size())return; if(current==i){if(playbackService!=null)playbackService.stopPlayback();current=-1;nowPlaying.setText("尚未选择歌曲");playButton.setText("播放");} tracks.remove(i); names.remove(i); saveLibrary(); adapter.notifyDataSetChanged();refreshLandscapeGrid(); if(headingView!=null)headingView.setText("本地歌曲  ·  "+names.size()); Toast.makeText(this,"已移除歌曲",Toast.LENGTH_SHORT).show();}
