    private void updateLike(){if(likeButton==null)return;if(current<0||current>=tracks.size()){likeButton.setVisibility(View.VISIBLE);likeButton.setEnabled(false);return;}Uri uri=tracks.get(current);PluginManager.PluginInfo source="plugin".equals(uri.getScheme())?sourceInfo(uri.getAuthority()):null;boolean supported=source==null||source.supports(episode(uri)?"likeEpisode":"like");likeButton.setVisibility(supported?View.VISIBLE:View.INVISIBLE);likeButton.setEnabled(!likePending.contains(uri.toString()));likeButton.setText("");likeButton.setContentDescription(liked.contains(uri.toString())?"取消收藏":"收藏歌曲");AppIcons.apply(likeButton,"heart",liked.contains(uri.toString()));}

    private void toggleLocalLike(String key){if(liked.contains(key))liked.remove(key);else liked.add(key);saveLiked();updateLike();}
    private JSONObject likeArgs(String id,boolean on){JSONObject args=SourceBrowser.arg("id",id);try{args.put("on",on);}catch(JSONException ignored){}return args;}
    private void toggleLike(){
        if(current<0||current>=tracks.size())return;String key=tracks.get(current).toString();Uri uri=tracks.get(current);if(!"plugin".equals(uri.getScheme())){toggleLocalLike(key);return;}PluginManager.PluginInfo source=sourceInfo(uri.getAuthority());String method=episode(uri)?"likeEpisode":"like";
        if(source==null||!source.supports(method)){showPluginError("此来源未提供这项收藏接口");return;}if(likePending.contains(key))return;boolean desired=!liked.contains(key);likePending.add(key);updateLike();
        pluginManager.export(source.id,method,likeArgs(uri.getQueryParameter("id"),desired),(ok,raw)->{likePending.remove(key);if(ok){if(desired)liked.add(key);else liked.remove(key);saveLiked();}else showSourceError(source.id,raw,"收藏操作失败",()->{if(current>=0&&current<tracks.size()&&tracks.get(current).toString().equals(key))toggleLike();});updateLike();});
    }


