    private void showBackup(){new AlertDialog.Builder(this).setTitle("备份与恢复").setMessage("导出或导入本地账号数据。音乐文件本身不会被复制。\n\n包含：音乐库、收藏、歌单、最近播放、评论和昵称。").setPositiveButton("导出",(d,w)->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"mygo-music-backup.json");startActivityForResult(i,EXPORT_DATA);}).setNeutralButton("导入",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT_DATA);}).setNegativeButton("关闭",null).show();}
    private String backupJson(){try{JSONObject o=new JSONObject();for(String k:new String[]{"uris","names","liked","playlists","recent","comments","account_name","local_lyrics","lyrics_offsets"})o.put(k,prefs.getString(k,""));return o.toString(2);}catch(Exception e){return "{}";}}
    private void writeBackup(Uri u){try{OutputStream out=getContentResolver().openOutputStream(u);out.write(backupJson().getBytes("UTF-8"));out.close();Toast.makeText(this,"备份已导出",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"导出失败",Toast.LENGTH_SHORT).show();}}
    private void readBackup(Uri u){try{InputStream in=getContentResolver().openInputStream(u);ByteArrayOutputStream buf=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))>0)buf.write(b,0,n);in.close();JSONObject o=new JSONObject(new String(buf.toByteArray(),"UTF-8"));SharedPreferences.Editor e=prefs.edit();for(String k:new String[]{"uris","names","liked","playlists","recent","comments","account_name","local_lyrics","lyrics_offsets"})if(o.has(k))e.putString(k,o.optString(k,""));e.apply();Toast.makeText(this,"备份已导入，正在刷新",Toast.LENGTH_SHORT).show();recreate();}catch(Exception e){Toast.makeText(this,"导入失败，文件格式不正确",Toast.LENGTH_SHORT).show();}}
