    private void showAudioCache(){ArrayList<AudioCache.Entry> entries=audioCache.list();LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(16),dp(8),dp(16),dp(8));box.addView(text(entries.size()+" 首 · "+cacheSize(audioCache.bytes())+" / 512 MB",16,Color.WHITE));box.addView(text("自动缓存会额外下载完整音频，完成后可离线播放；单曲上限 128 MB，超出总容量时清理较久未使用的歌曲。",13,Color.LTGRAY));Switch automatic=new Switch(this);automatic.setText("自动缓存播放过的插件歌曲");automatic.setChecked(prefs.getBoolean("auto_cache",true));automatic.setOnCheckedChangeListener((button,on)->prefs.edit().putBoolean("auto_cache",on).apply());box.addView(automatic);String status=audioCache.busy()?"正在缓存音频…":prefs.getString("cache_status","");if(!status.isEmpty())box.addView(text(status,13,Color.LTGRAY));for(AudioCache.Entry entry:entries){Button song=landscapeButton(entry.title+" · "+cacheSize(entry.bytes));box.addView(song,new LinearLayout.LayoutParams(-1,dp(48)));song.setOnClickListener(view->{Uri uri=Uri.parse(entry.track);addRemote(uri,entry.title,"");prefs.edit().putString("play_quality",entry.quality).apply();playIndex(tracks.indexOf(uri));});}AlertDialog dialog=new AlertDialog.Builder(this).setTitle("离线缓存").setView(scrollContent(box)).setNeutralButton("刷新",null).setPositiveButton("清理缓存",null).setNegativeButton("关闭",null).create();dialog.setOnShowListener(value->{dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(view->{dialog.dismiss();showAudioCache();});dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view->new AlertDialog.Builder(this).setTitle("清理离线缓存").setMessage("将删除已缓存的音频，并停止正在播放的缓存歌曲。歌单和收藏会保留。").setNegativeButton("取消",null).setPositiveButton("清理",(confirm,which)->{stopCachedPlayback();audioCache.clear();prefs.edit().remove("cache_status").apply();dialog.dismiss();showAudioCache();}).show());});dialog.show();}
    private void showAudioNormalization(){new AlertDialog.Builder(this).setTitle("播放与离线缓存").setMultiChoiceItems(new String[]{"音量均衡","自动缓存完整音频"},new boolean[]{prefs.getBoolean("normalize",true),prefs.getBoolean("auto_cache",true)},(dialog,index,enabled)->{prefs.edit().putBoolean(index==0?"normalize":"auto_cache",enabled).apply();if(playbackService!=null)playbackService.refreshVolume();}).setPositiveButton("完成",null).show();}
