    private void showSleepTimer(){if(playbackService==null){Toast.makeText(this,"请先播放歌曲",Toast.LENGTH_SHORT).show();return;}PlaybackService.Snapshot state=playbackService.snapshot();String status=state.sleepAfterTrack?"本曲结束后暂停":state.sleepRemaining>0?"剩余 "+((state.sleepRemaining+59999)/60000)+" 分钟":"当前未开启";new AlertDialog.Builder(this).setTitle("定时暂停 · "+status).setItems(new String[]{"关闭定时暂停","播完本曲后暂停","15 分钟后暂停","30 分钟后暂停","60 分钟后暂停"},(dialog,choice)->{if(playbackService!=null){playbackService.setSleepTimer(choice<2?0:new long[]{0,0,900000,1800000,3600000}[choice],choice==1);Toast.makeText(this,choice==0?"已取消定时暂停":choice==1?"本曲自然结束后暂停，手动切歌会取消":"定时暂停已开启，可在后台生效",Toast.LENGTH_LONG).show();}}).setNegativeButton("返回",null).show();}
